/// The ids tried, in order, when resolving `model_id`.
///
/// 1. The id as given, trimmed.
/// 2. Its bare name after the last slash, so a provider-qualified route
///    (`openai/gpt-4o`, `vertex-ai/gemini-3.7-flash`) finds the direct row
///    when the qualified row is absent.
/// 3. For Claude ids only, the dotted release suffix rewritten with dashes, so
///    `anthropic/claude-opus-5.5` finds `claude-opus-5-5`. The rewrite is
///    limited to Claude because OpenAI spells versions with a dot in the
///    canonical id (`gpt-4.1`), and dashing it would cross into a different
///    family.
///
/// 4. For any candidate without a slash, the namespaced id that alone carries
///    that bare name (`gpt-4` finds `openai/gpt-4`), from [`BARE_ALIASES`].
///
/// OpenRouter variant suffixes (`:free`, `:thinking`) are deliberately not
/// stripped: a variant can have a different window and price from its base.
///
/// The TypeScript and Python bindings implement the same steps. All three are
/// held to the answers in `model_facts_resolution.generated.json`, which the
/// generator computes from one reference implementation.
#[must_use]
pub fn model_facts_candidates(model_id: &str) -> Vec<String> {
    let trimmed = model_id.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    let mut candidates = vec![trimmed.to_owned()];
    let bare = trimmed.rsplit('/').next().unwrap_or(trimmed);
    if !bare.is_empty() && bare != trimmed {
        candidates.push(bare.to_owned());
    }
    for candidate in candidates.clone() {
        let name = candidate.rsplit('/').next().unwrap_or(candidate.as_str());
        if name.starts_with("claude-") && name.contains('.') {
            candidates.push(candidate.replace('.', "-"));
        }
    }
    for candidate in candidates.clone() {
        if candidate.contains('/') {
            continue;
        }
        let alias = BARE_ALIASES
            .binary_search_by(|(bare, _)| bare.cmp(&candidate.as_str()))
            .ok()
            .map(|index| BARE_ALIASES[index].1.to_owned());
        if let Some(alias) = alias {
            candidates.push(alias);
        }
    }
    let mut unique: Vec<String> = Vec::with_capacity(candidates.len());
    for candidate in candidates {
        if !unique.contains(&candidate) {
            unique.push(candidate);
        }
    }
    unique
}

/// Facts for `model_id`, or `None` when no candidate id is catalogued.
#[must_use]
pub fn model_facts(model_id: &str) -> Option<&'static ModelFacts> {
    model_facts_candidates(model_id)
        .iter()
        .find_map(|candidate| {
            MODEL_FACTS
                .binary_search_by(|(id, _)| id.cmp(&candidate.as_str()))
                .ok()
                .map(|index| &MODEL_FACTS[index].1)
        })
}
